mapper.select:
/** locgov-mapper.getLocgovListByParam (지자체관리 목록 조회) */ SELECT A.locgov_code, A.upper_locgov_nm, A.locgov_nm, A.upper_locgov_code, A.locgov_intrcn_cn, A.charger_cttpc AS charger_cttpc, A.charger_nm AS charger_nm, A.charger_psitn_dept, A.locgov_hmpg, A.locgov_popltn_co, A.locgov_ar, A.locgov_spcprd, A.gcct_use_at, A.etrcsh_use_at, A.use_at, A.locgov_budget_amt, A.bizrno, A.locgov_zip, A.bass_adres, A.dtl_adres, A.achlqr_sle_at, A.frst_register_id, DATE_FORMAT(A.frst_regist_pnttm,'%Y-%m-%d') AS frst_regist_pnttm, A.last_updusr_id, DATE_FORMAT(A.last_updt_pnttm,'%Y-%m-%d') AS last_updt_pnttm, (SELECT point_rate FROM g_ctbny_setup WHERE locgov_code = A.locgov_code AND stdr_year = DATE_FORMAT(now(), '%Y')) AS point_rate FROM (
SELECT L.locgov_code, L.upper_locgov_nm, L.locgov_nm, L.upper_locgov_code, L.locgov_intrcn_cn, L.charger_cttpc, L.charger_nm, L.charger_psitn_dept, L.locgov_hmpg, L.locgov_popltn_co, L.locgov_ar, L.locgov_spcprd, L.gcct_use_at, L.etrcsh_use_at, L.use_at, L.locgov_budget_amt, L.bizrno, L.locgov_zip, L.bass_adres, L.dtl_adres, L.achlqr_sle_at, L.frst_register_id, L.frst_regist_pnttm, L.last_updusr_id, L.last_updt_pnttm FROM g_locgov L
ORDER BY L.ordering
) A

/** locgov-mapper.getLocgovPointCountBySearchParam (포인트 목록 총 갯수 조회) */
SELECT COUNT(*)
FROM G_CTBNY_SETUP CS

/** locgov-mapper.getLocgovPointListBySearchParam (포인트 목록 조회) */ SELECT A.stdr_year, A.locgov_code, A.lmt_amt, A.point_rate, A.point_valid_pd, A.frst_register_id, DATE_FORMAT(A.frst_regist_pnttm,'%Y-%m-%d') AS frst_regist_pnttm, A.last_updusr_id, DATE_FORMAT(IFNULL(A.last_updt_pnttm, A.frst_regist_pnttm),'%Y-%m-%d') AS last_updt_pnttm, CASE WHEN IFNULL(M.user_name, '') != '' THEN M.user_name ELSE IFNULL(U.user_name, '') END AS last_updusr_name FROM (
SELECT CS.stdr_year, CS.locgov_code, CS.lmt_amt, CS.point_rate, CS.point_valid_pd, CS.frst_register_id, CS.frst_regist_pnttm, CS.last_updusr_id, CS.last_updt_pnttm FROM g_ctbny_setup CS
ORDER BY DATE_FORMAT(CS.last_updt_pnttm,'%Y-%m-%d') DESC, CS.stdr_year DESC
) A LEFT OUTER JOIN op_manager M ON M.user_id = IFNULL(A.last_updusr_id, A.frst_register_id) LEFT OUTER JOIN op_user U ON U.user_id = IFNULL(A.last_updusr_id, A.frst_register_id)

/** locgov-mapper.getContributionCountByLocgovCode (지자체 코드에 해당하는 기부 건수조회) */
SELECT COUNT(*)
FROM G_CNTR C



			C.CNTR_LOCGOV_CODE = #{locgovCode}

mapper.delete:
/** locgov-mapper.deleteLocgov (지자체 삭제) */
DELETE FROM
G_LOCGOV
WHERE LOCGOV_CODE = #{locgovCode}

/** locgov-mapper.deleteContributionSetup (기부금 설정 삭제) */
DELETE FROM G_CTBNY_SETUP
WHERE LOCGOV_CODE = #{locgovCode}

mapper.insert:
/** locgov-mapper.insertLocgov (지자체 등록) */ INSERT INTO G_LOCGOV ( LOCGOV_CODE, UPPER_LOCGOV_NM, LOCGOV_NM, UPPER_LOCGOV_CODE, LOCGOV_INTRCN_CN, CHARGER_CTTPC, CHARGER_NM, CHARGER_EMAIL, CHARGER_PSITN_DEPT, LOCGOV_HMPG, LOCGOV_POPLTN_CO, LOCGOV_AR, LOCGOV_SPCPRD, GCCT_USE_AT, ETRCSH_USE_AT, LOCGOV_BUDGET_AMT, BIZRNO, LOCGOV_ZIP, BASS_ADRES, DTL_ADRES, ACHLQR_SLE_AT, USE_AT, FRST_REGISTER_ID, FRST_REGIST_PNTTM, LAST_UPDUSR_ID, LAST_UPDT_PNTTM, PROCESS_DEPT_CODE, ADMINIST_INSTT_CODE, STDR_1LEVEL_AMT, STDR_2LEVEL_AMT, STDR_3LEVEL_AMT, OFFCS_NM, OFFCS_FILE_NM, ORGINL_FILE_NM, FIS_SP ) VALUES ( #{locgovCode}, (SELECT C.LABEL FROM OP_COMMON_CODE C WHERE C.CODE_TYPE = 'WDR' AND C.LANGUAGE = 'ko' AND C.USE_YN = 'Y' AND C.ID = #{upperLocgovCode} LIMIT 1), (SELECT C.LABEL FROM OP_COMMON_CODE C WHERE C.CODE_TYPE = 'LOCGOV_CODE' AND C.LANGUAGE = 'ko' AND C.USE_YN = 'Y' AND C.ID = #{locgovCode} LIMIT 1), #{upperLocgovCode}, #{locgovIntrcnCn}, #{chargerCttpc}, #{chargerNm}, #{chargerEmail}, #{chargerPsitnDept}, #{locgovHmpg}, #{locgovPopltnCo}, #{locgovAr}, #{locgovSpcprd}, #{gcctUseAt}, #{etrcshUseAt}, #{locgovBudgetAmt}, #{bizrno}, #{locgovZip}, #{bassAdres}, #{dtlAdres}, #{achlqrSleAt}, 'Y', #{frstRegisterId},
, #{lastUpdusrId},
, #{processDeptCode}, #{administInsttCode}, nvl(#{stdr1levelAmt}, 0), nvl(#{stdr2levelAmt}, 0), nvl(#{stdr3levelAmt}, 0), #{offcsNm}, #{offcsFileNm}, #{orginlFileNm}, #{fisSp} )

mapper.update:
/** locgov-mapper.updateContributionSetup (기부금 설정 수정) */
UPDATE
		G_CTBNY_SETUP
SET
		LAST_UPDUSR_ID = #{lastUpdusrId},
		LAST_UPDT_PNTTM = ,
		POINT_RATE = #{pointRate}
WHERE
		STDR_YEAR = #{stdrYear}
AND
		LOCGOV_CODE = #{locgovCode}

mapper.delete:
/** locgov-mapper.deleteHonorCntrUser (명예기부자 삭제) */
DELETE FROM G_HONOR_CNTRBTR
WHERE STDR_YEAR = year(now())
  AND LOCGOV_CODE = #{locgovCode}

mapper.insert:
		/** locgov-mapper.insertLocgov (명예기부자 등록) */
		INSERT INTO G_HONOR_CNTRBTR (
			STDR_YEAR,
			LOCGOV_CODE,
			USER_ID,
			HONOR_CNTRBTR_LEVEL_CODE,
			FRST_REGISTER_ID,
			FRST_REGIST_PNTTM,
			LAST_UPDUSR_ID,
			LAST_UPDT_PNTTM
		)
		SELECT year(now()),
			   #{locgovCode},
		       USER_ID,
		       ( case

		       		when amt  >=  #{stdr3levelAmt} then #{stdr3levelAmtCode}


		       		when amt  >=  #{stdr2levelAmt} then #{stdr2levelAmtCode}


		       		when amt  >=  #{stdr1levelAmt} then #{stdr1levelAmtCode}

		       	 end
		       ),
               #{lastUpdusrId},
               ,
               #{lastUpdusrId},

         FROM ( SELECT USER_ID,
                       SUM(CNTR_AMT) AS AMT
                  FROM G_CNTR
                 WHERE YEAR(STTEMNT_PAY_DE) = YEAR(NOW())
                   AND CNTR_LOCGOV_CODE = #{locgovCode}
                   AND DELETE_AT = 'N'
				   AND CNTR_STTUS_CODE = '200'
		           AND STTEMNT_PAY_DE IS NOT NULL
                 GROUP BY USER_ID


                		HAVING SUM(CNTR_AMT)  >=  #{stdr1levelAmt}


                		HAVING SUM(CNTR_AMT)  >=  #{stdr2levelAmt}


                		HAVING SUM(CNTR_AMT)  >=  #{stdr3levelAmt}


              )

