mapper.insert:
/** locgov-mapper.insertLocgovDeptHist (부서 코드 변경 등록) */
SELECT NVL(MAX(DEPT_HIST_NO) + 1, 1) AS DEPT_HIST_NO FROM G_LOCGOV_DEPT_HIST WHERE LOCGOV_CODE = #{locgovCode}
INSERT INTO G_LOCGOV_DEPT_HIST ( LOCGOV_CODE, DEPT_HIST_NO, PROCESS_DEPT_CODE, FRST_REGISTER_ID, FRST_REGIST_PNTTM, LAST_UPDUSR_ID, LAST_UPDT_PNTTM ) VALUES ( #{locgovCode}, #{deptHistNo}, #{processDeptCode}, #{frstRegisterId}, , #{frstRegisterId},
)

mapper.select:
/** locgov-mapper.getLocgovDeptHistListCount (부서 코드 변경 이력 총 갯수) */
SELECT count(*)
  FROM G_LOCGOV_DEPT_HIST A
 WHERE 1 = 1

   AND A.LOCGOV_CODE = #{locgovCode}

 ORDER BY A.LAST_UPDT_PNTTM DESC

/** locgov-mapper.getLocgovDeptHistList (부서 코드 변경 이력 조회) */ SELECT C.locgov_code, C.dept_hist_no, C.process_dept_code, C.last_updusr_id, C.last_updt_pnttm, C.user_name AS user_name, C.login_id AS login_id FROM ( SELECT locgov_code, dept_hist_no, process_dept_code, last_updusr_id, last_updt_pnttm, user_name, login_id FROM (
SELECT A.locgov_code, A.dept_hist_no, A.process_dept_code, A.last_updusr_id, DATE_FORMAT(A.last_updt_pnttm,'%Y-%m-%d') AS last_updt_pnttm, user_name AS user_name, login_id AS login_id FROM g_locgov_dept_hist A LEFT OUTER JOIN op_user B ON A.last_updusr_id = B.user_id WHERE 1 = 1
AND A.locgov_code = #{locgovCode}
ORDER BY A.last_updt_pnttm DESC
) )C

/** locgov-mapper.getLocgovOffcsInfo (직인 파일 정보 가져오기) */
SELECT OFFCS_NM
       ,OFFCS_FILE_NM
       ,ORGINL_FILE_NM
  FROM G_LOCGOV
 WHERE LOCGOV_CODE = #{locgovCode}

mapper.update:
/** locgov-mapper.updateLocgovOffcsInfo (직인 파일 정보 삭제) */
UPDATE G_LOCGOV
   SET OFFCS_NM = null
       ,OFFCS_FILE_NM = null
       ,ORGINL_FILE_NM = null
 WHERE LOCGOV_CODE = #{locgovCode}

