/** locgov-mapper.getLocgovCodeById (관리자 자치구 코드 가져오기) */
SELECT LOCGOV_CODE
  FROM OP_MANAGER
 WHERE USER_ID = #{userId}

/** locgov-mapper.getLocgovCodeById (답례품업체 자치구 코드 가져오기) */
SELECT LOCGOV_CODE
  FROM OP_SELLER
 WHERE SELLER_ID = #{userId}

/** locgov-mapper.getLocgovCodeById (답례품관리자 자치구 코드 가져오기) */
SELECT LOCGOV_CODE
FROM OP_SELLER_USER
WHERE USER_ID = #{userId}

/** locgov-mapper.getUpperLocgovCode (상위지자체 코드 가져오기) */
SELECT UPPER_LOCGOV_CODE
FROM G_LOCGOV
WHERE LOCGOV_CODE = #{locgov}
